resultDetails.input:
{
  "message": "The requested GR-COVER-01 scope says executable tests/dataset cases are required only for the listed technical identifiers. Existing GR-EVAL-01/02/03 still name `evaluation_threshold_declared_and_unchanged` and `evaluation_integrity_no_case_or_guardrail_tampering` as guardrail tests, and GR-COVER-01 currently names `required_coverage_executable`. How should these nontechnical verification IDs be handled so the amendment preserves the other guardrails without contradicting the new “only” rule?",
  "requestedSchema": {
    "properties": {
      "verification_scope": {
        "type": "string",
        "title": "Nontechnical guardrail verification",
        "description": "Choose how to reconcile the existing evaluation/coverage checks with the new test-scope rule.",
        "oneOf": [
          {
            "const": "manual_checklist",
            "title": "Use manual harness-log checklist checks for these IDs; retain their guardrail requirements"
          },
          {
            "const": "keep_executable",
            "title": "Keep these as executable guardrail checks in addition to the listed technical IDs"
          },
          {
            "const": "other",
            "title": "Provide another precise interpretation"
          }
        ],
        "default": "manual_checklist"
      }
    }
  }
}
